INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','prepositions-of-place','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"prepositions-of-place","title":"Prepositions of place","level":"A1","order":18,"summary":"Use in for containment, on for surfaces, and at for activity locations and points.","learningGoals":["Inside a space","On a surface","At a point or activity"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Inside a space","explanation":"In locates something within a container, area, city or country. Read the stated physical relation carefully.","examples":["The tools are in a chest.","The village is in a valley."]},{"title":"On a surface","explanation":"On describes contact with a surface, including vertical surfaces. It does not simply mean higher than something.","examples":["The chart is on the wall.","The cloth is on the counter."]},{"title":"At a point or activity","explanation":"At often marks an exact point or an activity location. Expressions such as at home and at work are conventional. Some places allow different prepositions with different meanings; each question specifies its intended meaning.","examples":["Meet me at the entrance.","She is at work."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-prepositions-of-place"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"cd3093a9-de71-52fd-ad17-21db7a61b9dd","topicSlug":"prepositions-of-place","level":"A1","prompt":"Locate a cheque, inside the envelope, not attached to its surface: A cheque is ____ the sealed envelope.","choices":[{"id":"A","text":"into"},{"id":"B","text":"in"},{"id":"C","text":"on"},{"id":"D","text":"at"}],"answerId":"B","hint":"In locates something within a container, area, city or country. Read the stated physical relation carefully. Focus on **location preposition** in this question.","explanation":"Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface.","keywords":[],"source":"seed","skill":"location-preposition","contextKey":"place-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-of-place"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"b2815697c94e728a682863cea87e40c933460892c1e392e2504216f2193d1ac9","teaching":{"steps":["Identify what the question tests: **location preposition**. In locates something within a container, area, city or country. Read the stated physical relation carefully.","Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface.","Choose **in**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**into** describes movement into a space, which is not the relation specified in this question. Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface.","B":"Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface.","C":"**on** describes contact with a surface, which is not the relation specified in this question. Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface.","D":"**at** describes a point or conventional activity location, which is not the relation specified in this question. Use in the sealed envelope for the stated relation: inside the envelope, not attached to its surface."}}},{"id":"68a0debf-fee4-5283-abaa-0e768b10e019","topicSlug":"prepositions-of-place","level":"A1","prompt":"Give the static location of a cheque: inside the envelope, not attached to its surface. Choose the phrase.","choices":[{"id":"A","text":"in the sealed envelope"},{"id":"B","text":"on the sealed envelope"},{"id":"C","text":"at the sealed envelope"},{"id":"D","text":"into the sealed envelope"}],"answerId":"A","hint":"In locates something within a container, area, city or country. Read the stated physical relation carefully. Focus on **location phrase** in this question.","explanation":"The requested location is in the sealed envelope. Into describes movement, not the static relation requested here.","keywords":[],"source":"seed","skill":"location-phrase","contextKey":"place-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-of-place"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"5b8a4fdef126acef02823d4ccd70cd71bb80e0c4311d22124767456369af33ec","teaching":{"steps":["Identify what the question tests: **location phrase**. In locates something within a container, area, city or country. Read the stated physical relation carefully.","The requested location is in the sealed envelope. Into describes movement, not the static relation requested here.","Choose **in the sealed envelope**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"The requested location is in the sealed envelope. Into describes movement, not the static relation requested here.","B":"**on the sealed envelope** describes contact with a surface, which is not the relation specified in this question. The requested location is in the sealed envelope. Into describes movement, not the static relation requested here.","C":"**at the sealed envelope** describes a point or conventional activity location, which is not the relation specified in this question. The requested location is in the sealed envelope. Into describes movement, not the static relation requested here.","D":"**into the sealed envelope** describes movement into a space, which is not the relation specified in this question. The requested location is in the sealed envelope. Into describes movement, not the static relation requested here."}}},{"id":"c00a2213-b8a1-53bc-ad0a-f9597ad95663","topicSlug":"prepositions-of-place","level":"A1","prompt":"In “a cheque in the sealed envelope”, with the meaning “inside the envelope, not attached to its surface”, what relation does in express?","choices":[{"id":"A","text":"Within a space or container"},{"id":"B","text":"In contact with a surface"},{"id":"C","text":"At a conventional activity location or a point"},{"id":"D","text":"Movement into a space"}],"answerId":"A","hint":"In locates something within a container, area, city or country. Read the stated physical relation carefully. Focus on **spatial meaning** in this question.","explanation":"Here, in describes inside the envelope, not attached to its surface. The same place can take another preposition if its meaning changes.","keywords":[],"source":"seed","skill":"spatial-meaning","contextKey":"place-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-of-place"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"e752c064de498e429900c1b7efa5e355626e6ead2fa64438549aadaaa9898982","teaching":{"steps":["Identify what the question tests: **spatial meaning**. In locates something within a container, area, city or country. Read the stated physical relation carefully.","Here, in describes inside the envelope, not attached to its surface. The same place can take another preposition if its meaning changes.","Choose **Within a space or container**. Check the completed express